import { 
  View, 
  Text, 
  Pressable, 
  FlatList{{#if (eq styling "stylesheet")}}, 
  StyleSheet{{/if}} 
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
{{#if (eq icons "lucide")}}
import { Star, SlidersHorizontal } from 'lucide-react-native';
{{/if}}

const products = [
  { id: '1', title: 'Wireless Earbuds Pro', price: '$129.00', rating: 4.8, color: '#DBEAFE' },
  { id: '2', title: 'Smart Watch Series 5', price: '$249.00', rating: 4.6, color: '#FCE7F3' },
  { id: '3', title: 'Portable Speaker Mini', price: '$59.00', rating: 4.4, color: '#D1FAE5' },
  { id: '4', title: 'USB-C Fast Charger', price: '$39.00', rating: 4.7, color: '#FEF3C7' },
  { id: '5', title: 'Bluetooth Keyboard', price: '$79.00', rating: 4.5, color: '#E0E7FF' },
  { id: '6', title: 'Noise-Cancelling Headphones', price: '$199.00', rating: 4.9, color: '#FEE2E2' },
];

export default function ProductsScreen() {
  return (
    <SafeAreaView {{#if (eq styling "nativewind")}}className="flex-1 bg-gray-50"{{else}}style={styles.safeArea}{{/if}} edges={['top']}>
      {/* Header */}
      <View {{#if (eq styling "nativewind")}}className="flex-row items-center justify-between px-5 pt-4 pb-4"{{else}}style={styles.header}{{/if}}>
        <Text {{#if (eq styling "nativewind")}}className="text-2xl font-bold text-gray-900"{{else}}style={styles.title}{{/if}}>
          Shop
        </Text>
        {{#if (eq icons "lucide")}}
        <Pressable {{#if (eq styling "nativewind")}}className="h-10 w-10 items-center justify-center rounded-full bg-white"{{else}}style={styles.filterButton}{{/if}}>
          <SlidersHorizontal size={20} color="#4B5563" />
        </Pressable>
        {{/if}}
      </View>

      <FlatList
        data={products}
        keyExtractor={(item) => item.id}
        numColumns={2}
        contentContainerStyle={styles.grid}
        columnWrapperStyle={styles.gridRow}
        renderItem={({ item }) => (
          <Pressable {{#if (eq styling "nativewind")}}className="mb-4 flex-1 rounded-2xl bg-white p-4"{{else}}style={styles.card}{{/if}}>
            <View
              {{#if (eq styling "nativewind")}}className="h-36 w-full items-center justify-center rounded-xl"{{else}}style={styles.imagePlaceholder}{{/if}}
            >
              <View {{#if (eq styling "nativewind")}}className="h-20 w-20 rounded-2xl"{{else}}style={[styles.imageBlock, { backgroundColor: item.color }]}{{/if}} />
            </View>
            <Text {{#if (eq styling "nativewind")}}className="mt-3 text-sm font-medium text-gray-900"{{else}}style={styles.cardTitle}{{/if}} numberOfLines={2}>
              {item.title}
            </Text>
            <View {{#if (eq styling "nativewind")}}className="mt-2 flex-row items-center justify-between"{{else}}style={styles.cardFooter}{{/if}}>
              <Text {{#if (eq styling "nativewind")}}className="text-base font-bold text-gray-900"{{else}}style={styles.price}{{/if}}>{item.price}</Text>
              <View {{#if (eq styling "nativewind")}}className="flex-row items-center gap-1"{{else}}style={styles.rating}{{/if}}>
                {{#if (eq icons "lucide")}}
                <Star size={14} color="#F59E0B" fill="#F59E0B" />
                {{/if}}
                <Text {{#if (eq styling "nativewind")}}className="text-xs text-gray-500"{{else}}style={styles.ratingText}{{/if}}>{item.rating}</Text>
              </View>
            </View>
          </Pressable>
        )}
      />
    </SafeAreaView>
  );
}

{{#if (eq styling "stylesheet")}}
const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F9FAFB',
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 20,
    paddingTop: 16,
    paddingBottom: 16,
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#111827',
  },
  filterButton: {
    height: 40,
    width: 40,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 20,
    backgroundColor: '#FFFFFF',
  },
  grid: {
    paddingHorizontal: 20,
    paddingBottom: 24,
  },
  gridRow: {
    gap: 12,
  },
  card: {
    marginBottom: 16,
    flex: 1,
    borderRadius: 16,
    backgroundColor: '#FFFFFF',
    padding: 16,
  },
  imagePlaceholder: {
    height: 144,
    width: '100%',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 12,
    backgroundColor: '#F3F4F6',
  },
  imageBlock: {
    height: 80,
    width: 80,
    borderRadius: 16,
  },
  cardTitle: {
    marginTop: 12,
    fontSize: 14,
    fontWeight: '500',
    color: '#111827',
  },
  cardFooter: {
    marginTop: 8,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  price: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#111827',
  },
  rating: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  ratingText: {
    fontSize: 12,
    color: '#6B7280',
  },
});
{{/if}}
